///|
async fn worker_alive(directory : String) -> Bool {
  let lock = @fs.open(
    directory + "/worker.lock",
    mode=ReadWrite,
    create_mode=OpenOrCreate,
    permission=0o600,
  )
  defer lock.close()
  !lock.try_lock(Exclusive)
}

///|
async fn tunnel_status(
  directory : String,
  status : String,
  recording? : Bool,
) -> Unit {
  let value : Json = { "status": status, "runId": recording_run_id }
  @fs.write_file(directory + "/status.tmp", value.stringify(), permission=0o600)
  @fs.rename(
    directory + "/status.tmp",
    directory + "/status.json",
    replace=true,
  )
  save_diagnostic("orca-tunnel", status, tunnel_directory=directory, recording?)
}

///|
async fn connection_failure(
  directory : String,
  names : Array[String],
) -> String? {
  for name in names {
    let event = @json.parse(@fs.read_file(directory + "/" + name).text()) catch {
      _ => Json::null()
    }
    if field(event, "detail") is Some(Json::String(detail)) && detail != "" {
      return Some(detail)
    }
  }
  None
}

///|
async fn save_connection_failure(
  directory : String,
  name : String,
  detail : String,
) -> Unit {
  let value : Json = { "detail": detail }
  let temporary = directory + "/" + name + ".tmp"
  @fs.write_file(temporary, value.stringify(), permission=0o600)
  @fs.rename(temporary, directory + "/" + name, replace=true)
}

///|
async fn adapter_executable() -> String {
  let name = @env.args()[0]
  if name.contains("/") {
    return @fs.realpath(name)
  }
  for directory in @env.get_env_var("PATH").unwrap_or("").split(":") {
    let path = directory.to_owned() + "/" + name
    if @fs.exists(path) {
      return @fs.realpath(path)
    }
  }
  raise AdapterError("Adapter executable is unavailable for tunnel recovery")
}

