    assert(timings.length < 4096, "Timing recording limit exceeded");
    timings.push({ operation, workspace, elapsedMs: Math.ceil(performance.now() - started), targetMs: Math.max(0, budgetMs - bufferMs), budgetMs, ok });
  }
}

